<?php
namespace BeeUpdater;
final class CriticalAuth {
 public function authenticate(string $email,string $password,string $mfaCode=''):array{
  $pdo=Common::pdo();$pdo->beginTransaction();
  try{$has=(bool)$pdo->query("SHOW COLUMNS FROM users LIKE 'mfa_last_timestep'")->fetch();$expr=$has?'u.mfa_last_timestep':'NULL AS mfa_last_timestep';$s=$pdo->prepare("SELECT u.id,u.password,u.mfa_secret,u.mfa_recovery_codes,u.mfa_confirmed_at,{$expr},r.name role FROM users u LEFT JOIN roles r ON r.id=u.platform_role_id WHERE u.email=? AND u.status='ACTIVE' LIMIT 1 FOR UPDATE");$s->execute([$email]);$u=$s->fetch();if(!$u||!in_array($u['role'],['PLATFORM_OWNER','PLATFORM_ADMIN'],true)||!password_verify($password,(string)$u['password'])){$pdo->rollBack();return['ok'=>false,'reason'=>'invalid'];}
   if(Common::envBool('BEE_REQUIRE_ADMIN_MFA',true)){if(empty($u['mfa_confirmed_at'])||empty($u['mfa_secret'])){$pdo->rollBack();return['ok'=>false,'reason'=>'mfa_enrollment_required'];}$secret=$this->decryptString((string)$u['mfa_secret']);$accepted=false;$counter=(new TotpVerifier())->matchedCounter($secret,$mfaCode);$last=$has?($u['mfa_last_timestep']===null?null:(int)$u['mfa_last_timestep']):$this->overlayLastCounter((string)$u['id']);if($counter!==null&&($last===null||$counter>$last)){if($has){$q=$pdo->prepare('UPDATE users SET mfa_last_timestep=?,updated_at=NOW() WHERE id=? AND (mfa_last_timestep IS NULL OR mfa_last_timestep<?)');$q->execute([$counter,$u['id'],$counter]);$accepted=$q->rowCount()===1;}else{$this->writeOverlayCounter((string)$u['id'],$counter);$accepted=true;}}
    if(!$accepted){$h=hash('sha256',strtoupper(trim($mfaCode)));$codes=$this->decryptRecoveryCodes((string)($u['mfa_recovery_codes']??''));$idx=array_search($h,$codes,true);if($idx!==false){unset($codes[$idx]);$q=$pdo->prepare('UPDATE users SET mfa_recovery_codes=?,updated_at=NOW() WHERE id=?');$q->execute([$this->encryptString(json_encode(array_values($codes),JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),$u['id']]);$accepted=true;}}
    if(!$accepted){$pdo->rollBack();return['ok'=>false,'reason'=>'mfa_invalid'];}}
   $pdo->commit();return['ok'=>true,'user'=>['id'=>$u['id'],'role'=>$u['role']]];
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 private function decryptRecoveryCodes(string$value):array{if($value==='')return[];$plain=$this->decryptString($value);$codes=json_decode($plain,true);return is_array($codes)?array_values(array_filter($codes,'is_string')):[];}
 private function decryptString(string$value):string{try{return(string)$this->encrypter()->decrypt($value,false);}catch(\Throwable){throw new \RuntimeException('Encrypted MFA material cannot be decrypted with APP_KEY.');}}
 private function encryptString(string$value):string{return(string)$this->encrypter()->encrypt($value,false);}
 private function encrypter():\Illuminate\Encryption\Encrypter{$e=Common::env();$raw=(string)($e['APP_KEY']??'');if($raw==='')throw new \RuntimeException('APP_KEY is required for critical MFA reauthentication.');$key=str_starts_with($raw,'base64:')?base64_decode(substr($raw,7),true):$raw;if($key===false||$key==='')throw new \RuntimeException('APP_KEY is invalid.');$cipher=(string)($e['APP_CIPHER']??'AES-256-CBC');return new \Illuminate\Encryption\Encrypter($key,$cipher);}
 private function overlayStatePath():string{return Common::base().'/storage/app/private/overlay-mfa-state.json';}
 private function overlayLastCounter(string$id):?int{$p=$this->overlayStatePath();$d=is_file($p)?(json_decode((string)file_get_contents($p),true)?:[]):[];$v=$d['users'][$id]??null;return$v===null?null:(int)$v;}
 private function writeOverlayCounter(string$id,int$c):void{$p=$this->overlayStatePath();$dir=dirname($p);if(!is_dir($dir))mkdir($dir,0700,true);$fh=fopen($p,'c+');if(!$fh)throw new \RuntimeException('Cannot persist overlay MFA state.');try{if(!flock($fh,LOCK_EX))throw new \RuntimeException('Cannot lock overlay MFA state.');rewind($fh);$raw=stream_get_contents($fh);$d=$raw!==false&&trim($raw)!==''?(json_decode($raw,true)?:[]):[];$d['users'][$id]=$c;$d['updated_at']=gmdate('c');ftruncate($fh,0);rewind($fh);fwrite($fh,json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));fflush($fh);flock($fh,LOCK_UN);}finally{fclose($fh);}@chmod($p,0600);}
}
